  output [31:0] io_result,
  output        io_zero_flag
);

  reg  [31:0] casez_tmp;
  wire [31:0] _GEN = {27'h0, io_B[4:0]};
  wire [62:0] _io_result_T_8 = {31'h0, io_A} << io_B[4:0];
  always @(*) begin
    casez (io_alu_control)
      4'b0000:
        casez_tmp = io_A + io_B;
      4'b0001:
        casez_tmp = io_A - io_B;
      4'b0010:
        casez_tmp = io_A & io_B;
      4'b0011:
        casez_tmp = {31'h0, $signed(io_A) < $signed(io_B)};
      4'b0100:
        casez_tmp = io_A ^ io_B;
      4'b0101:
        casez_tmp = {31'h0, io_A < io_B};
      4'b0110:
        casez_tmp = io_A | io_B;
      4'b0111:
        casez_tmp = $signed($signed(io_A) >>> _GEN);
      4'b1000:
        casez_tmp = io_A >> _GEN;
      4'b1001:
        casez_tmp = _io_result_T_8[31:0];
