        casez_tmp = 32'h0;
      4'b1011:
        casez_tmp = 32'h0;
      4'b1100:
        casez_tmp = 32'h0;
      4'b1101:
        casez_tmp = 32'h0;
      4'b1110:
        casez_tmp = 32'h0;
